import {astronomyPart3Additions} from './timeline-astronomy-part3.mjs';
import {astronomyPart4Additions} from './timeline-astronomy-part4.mjs';
import {astronomyPart5Additions} from './timeline-astronomy-part5.mjs';
// Milestones discussed in the site's astronomy serial.
// Uncertain archaeological interpretations are labelled as such in the dialog.
const serial='https://naukazamlade.com/sr/istorija-nauke/feljton-istorija-astronomije/';
const add=(key,sort,year,text,detail,file,alt,part=1)=>({
  key,sort,year:{sr:year[0],sl:year[1],en:year[2]},
  text:{sr:text[0],sl:text[1],en:text[2]},
  detail:{sr:detail[0],sl:detail[1],en:detail[2]},
  media:{file:`serial-astronomy/${file.includes('/')?file:`${part===1?'part1':'part2'}/${file}`}`,source:`${serial}deo-${part}/`,credit:'Ilustracija iz feljtona „Istorija astronomije“',license:'Ilustracija iz feljtona',alt}
});

export const astronomyAdditions=[
  add('serial-warren',-8000,['oko 8000. p. n. e.','ok. 8000 pr. n. št.','c. 8000 BCE'],
    ['Jame u Voren Fildu možda prate Mesečeve mesece.','Jame pri Warren Fieldu so morda sledile luninim mesecem.','Warren Field pits may have tracked lunar months.'],
    ['U Voren Fildu u Škotskoj pronađen je niz od dvanaest mezolitskih jama. Istraživači su predložili da odgovaraju lunarnim mesecima. Položaj niza povezan je i sa izlaskom Sunca oko zimskog solsticija. Zbog toga se lokalitet tumači kao mogući lunarno-solarni kalendar. Namena jama nije definitivno dokazana.',
     'Pri Warren Fieldu na Škotskem so odkrili niz dvanajstih mezolitskih jam. Raziskovalci so predlagali, da ustrezajo luninim mesecem. Razporeditev je povezana tudi s Sončevim vzhodom ob zimskem solsticiju. Zato kraj razlagajo kot morebitni lunisolarni koledar. Namen jam ni dokončno dokazan.',
     'A row of twelve Mesolithic pits was found at Warren Field in Scotland. Researchers proposed that they represent lunar months. The alignment also relates to sunrise around the winter solstice. The site is therefore interpreted as a possible lunisolar calendar. The pits’ purpose is not conclusively established.'],
    'image3.jpg','Twelve pits at the Warren Field archaeological site.'),
  add('serial-goseck',-4800,['oko 4800. p. n. e.','ok. 4800 pr. n. št.','c. 4800 BCE'],
    ['Gosečki krug povezuje gradnju sa zimskim solsticijem.','Goseški krog poveže gradnjo z zimskim solsticijem.','Goseck Circle aligns with the winter solstice.'],
    ['Neolitsko kružno ograđivanje u Goseku sastojalo se od rovova i drvenih ograda. Njegovi prolazi povezani su sa izlaskom i zalaskom Sunca oko zimskog solsticija. Takvo poravnanje pokazuje pažljivo opažanje godišnjeg Sunčevog puta. Nije poznato da li je građevina služila samo kao kalendar. Verovatno je imala i društvenu ili obrednu ulogu.',
     'Neolitsko krožno območje v Gosecku so sestavljali jarki in lesene ograde. Prehodi so povezani s Sončevim vzhodom in zahodom ob zimskem solsticiju. Takšna poravnava kaže skrbno spremljanje Sončeve letne poti. Ni znano, ali je stavba služila samo kot koledar. Verjetno je imela tudi družbeno ali obredno vlogo.',
     'The Neolithic Goseck enclosure consisted of ditches and wooden palisades. Its openings relate to sunrise and sunset near the winter solstice. This alignment shows careful observation of the Sun’s annual path. We do not know whether it served only as a calendar. It probably also had social or ceremonial roles.'],
    'image2.jpg','Reconstruction of the Goseck circular enclosure.'),
  add('serial-giza',-2500.2,['oko 2500. p. n. e.','ok. 2500 pr. n. št.','c. 2500 BCE'],
    ['Piramide u Gizi poravnate su sa stranama sveta.','Piramide v Gizi so poravnane s stranmi neba.','Giza pyramids align closely with cardinal directions.'],
    ['Stranice Velike piramide približno su poravnate sa geografskim severom, jugom, istokom i zapadom. Tačna metoda graditelja ostaje predmet istraživanja. Opažanje zvezda ili Sunčeve senke moglo je pomoći pri određivanju pravaca. Preciznost poravnanja govori o razvijenoj geometriji i merenju. Ona sama ne dokazuje svaku kasniju teoriju o astronomskom značenju piramide.',
     'Stranice Velike piramide so zelo blizu geografskemu severu, jugu, vzhodu in zahodu. Natančna metoda graditeljev ostaja predmet raziskav. Opazovanje zvezd ali Sončeve sence je lahko pomagalo določiti smeri. Natančnost kaže razvito geometrijo in merjenje. Sama po sebi pa ne dokazuje vseh poznejših teorij o astronomskem pomenu piramide.',
     'The Great Pyramid’s sides align closely with north, south, east and west. Its builders’ exact method remains under study. Observations of stars or solar shadows may have helped establish direction. The precision reflects advanced surveying and geometry. It does not by itself prove every later claim about the pyramid’s astronomical purpose.'],
    'image7.jpg','Ancient Egyptian merket used to establish directions.'),
  add('serial-babylon',-2000,['od oko 2000. p. n. e.','od ok. 2000 pr. n. št.','from c. 2000 BCE'],
    ['U Mesopotamiji se sistematski beleže nebeske pojave.','V Mezopotamiji sistematično zapisujejo nebesne pojave.','Mesopotamian observers systematically record the sky.'],
    ['Mesopotamski pisari beležili su pojavljivanje planeta, Meseca i Sunca na glinenim tablicama. Posmatranja su se prikupljala tokom mnogih pokolenja. Dugi nizovi podataka omogućili su prepoznavanje ponavljajućih ciklusa. Astronomija je tada bila povezana i sa kalendarom i sa predskazanjima. Sačuvane tablice važan su izvor za istoriju merenja neba.',
     'Mezopotamski pisarji so na glinenih tablicah beležili planete, Luno in Sonce. Opazovanja so zbirali skozi številne rodove. Dolgi nizi podatkov so omogočili prepoznavanje ponavljajočih se ciklov. Astronomija je bila povezana s koledarjem in prerokovanjem. Ohranjene tablice so pomemben vir za zgodovino merjenja neba.',
     'Mesopotamian scribes recorded appearances of planets, the Moon and the Sun on clay tablets. Observations accumulated over many generations. Long records made repeating cycles easier to recognize. Astronomy was linked to calendars and divination. Surviving tablets are major evidence for the history of sky measurement.'],
    'image6.jpg','Fragment of Mesopotamian celestial omen tablets.'),
  add('serial-kokino',-1800.2,['oko 1800. p. n. e.','ok. 1800 pr. n. št.','c. 1800 BCE'],
    ['Bronzanodobno Kokino ima moguće solarne orijentire.','Bronastodobni Kokino ima mogoče sončne oznake.','Bronze Age Kokino has possible solar alignments.'],
    ['Kokino u današnjoj Severnoj Makedoniji je arheološki lokalitet iz bronzanog doba. Na stenama postoje useci čija su poravnanja tumačena u vezi sa izlascima Sunca i Meseca. Takva tumačenja ukazuju na moguće obredno i kalendarsko korišćenje prostora. Međutim, nisu svi istraživači saglasni da je reč o opservatoriji u savremenom smislu. Lokalitet pokazuje koliko je važno razdvojiti arheološki nalaz od njegove interpretacije.',
     'Kokino v današnji Severni Makedoniji je arheološko najdišče iz bronaste dobe. Skalni zarezi so bili razloženi kot oznake Sončevih in Luninih vzhodov. To kaže na možno obredno in koledarsko rabo prostora. Vendar se vsi raziskovalci ne strinjajo, da gre za observatorij v sodobnem smislu. Kraj nas uči ločevati najdbo od njene razlage.',
     'Kokino in present-day North Macedonia is a Bronze Age archaeological site. Rock notches have been interpreted as alignments with Sun and Moon rises. This suggests possible ceremonial and calendrical uses. Researchers do not all agree that it was an observatory in the modern sense. The site illustrates the difference between an archaeological find and its interpretation.'],
    'image18.png','Rock formations at the Kokino archaeological site.'),
  add('serial-thales',-585,['585. p. n. e.','585 pr. n. št.','585 BCE'],
    ['Pomračenje Sunca postaje deo priče o Talesu.','Sončev mrk postane del zgodbe o Talesu.','A solar eclipse enters the story of Thales.'],
    ['Pomračenje Sunca 585. godine pre nove ere povezano je sa Talesom iz Mileta u antičkim izvorima. Herodot je napisao da ga je Tales unapred najavio. Istoričari raspravljaju da li je tada uopšte bilo moguće precizno predvideti mesto i dan takvog pomračenja. Predanje je ipak važno za istoriju traženja pravilnosti u prirodi. Ne treba ga predstavljati kao pouzdano dokazano precizno predviđanje.',
     'Sončev mrk leta 585 pred našim štetjem antični viri povezujejo s Talesom iz Mileta. Herodot je zapisal, da ga je Tales napovedal. Zgodovinarji razpravljajo, ali je bilo tedaj mogoče natančno napovedati kraj in dan mrka. Izročilo je vseeno pomembno za zgodovino iskanja naravnih zakonitosti. Ne smemo ga predstavljati kot zanesljivo dokazano natančno napoved.',
     'Ancient sources connect the solar eclipse of 585 BCE with Thales of Miletus. Herodotus wrote that Thales had foretold it. Historians debate whether a precise date and location could have been predicted then. The story remains significant in the search for patterns in nature. It should not be presented as a securely proven exact prediction.'],
    'image8.png','Modern artistic representation of Thales of Miletus.'),
  add('serial-democritus',-400,['oko 400. p. n. e.','ok. 400 pr. n. št.','c. 400 BCE'],
    ['Demokrit Mlečni put tumači kao mnoštvo zvezda.','Demokrit razloži Rimsko cesto kot množico zvezd.','Democritus proposes that the Milky Way is many stars.'],
    ['Demokrit je izneo zamisao da mlečna traka na nebu nastaje od velikog broja dalekih zvezda. Bez teleskopa nije mogao da ispita tu pretpostavku. Ideja se razlikovala od objašnjenja koja su se oslanjala na mitove. Mnogo kasnije teleskopska posmatranja pokazala su da se ta traka zaista razlaže na bezbroj zvezda. Njegova hipoteza primer je smelog prirodnog objašnjenja.',
     'Demokrit je predlagal, da svetli pas na nebu sestavljajo številne oddaljene zvezde. Brez teleskopa domneve ni mogel preizkusiti. Zamisel se je razlikovala od mitoloških razlag. Mnogo pozneje so teleskopska opazovanja pokazala množico zvezd v tem pasu. Njegova hipoteza je primer drznega naravnega pojasnila.',
     'Democritus suggested that the Milky Way’s pale band came from many distant stars. Without a telescope he could not test the idea. It differed from myth-based explanations. Much later telescopes resolved the band into countless stars. His proposal is an early example of a bold natural explanation.'],
    'external/milky-way-carl-young.jpg','The Milky Way across a dark sky.'),
  add('serial-aristarchus',-270,['oko 270. p. n. e.','ok. 270 pr. n. št.','c. 270 BCE'],
    ['Aristarh razmatra Sunce u središtu planetarnog sistema.','Aristarh razmišlja o Soncu v središču sistema.','Aristarchus proposes a Sun-centered arrangement.'],
    ['Aristarh sa Samosa predložio je da se Zemlja kreće oko Sunca. Geometrijski je pokušao i da uporedi udaljenosti Sunca i Meseca. Njegove brojčane procene bile su netačne zbog teških ugaonih merenja. Zaključio je, međutim, da je Sunce znatno dalje od Meseca. Njegova heliocentrična ideja nije postala opšteprihvaćena u antici.',
     'Aristarh s Samosa je predlagal, da se Zemlja giblje okoli Sonca. Z geometrijo je skušal primerjati razdalji do Sonca in Lune. Številčne ocene so bile napačne zaradi zahtevnega merjenja kotov. Vendar je sklenil, da je Sonce mnogo dlje od Lune. Njegova heliocentrična zamisel v antiki ni prevladala.',
     'Aristarchus of Samos proposed that Earth moves around the Sun. He also used geometry to compare the distances of Sun and Moon. His numerical estimates were inaccurate because the angles were hard to measure. He did infer that the Sun is much farther away than the Moon. His heliocentric proposal did not gain wide acceptance in antiquity.'],
    'image10.png','Diagram of Aristarchus’s Sun–Moon distance geometry.'),
  add('serial-eratosthenes',-240,['oko 240. p. n. e.','ok. 240 pr. n. št.','c. 240 BCE'],
    ['Eratosten procenjuje obim Zemlje pomoću senki.','Eratosten s sencami oceni obseg Zemlje.','Eratosthenes estimates Earth’s circumference with shadows.'],
    ['Eratosten je uporedio visinu Sunca u Sijeni i Aleksandriji. Razlika u uglu senki dala mu je deo punog kruga. Uz procenjenu udaljenost između gradova izračunao je obim Zemlje. Tačna veličina antičke jedinice stadij nije sasvim poznata. Metod je izuzetan zato što iz lokalnih opažanja izvodi meru čitave planete.',
     'Eratosten je primerjal višino Sonca v Sieni in Aleksandriji. Razlika v kotu senc mu je dala del polnega kroga. Z ocenjeno razdaljo med mestoma je izračunal Zemljin obseg. Točna dolžina antične enote stadij ni povsem znana. Metoda je izjemna, ker iz krajevnih opazovanj izpelje mero celotnega planeta.',
     'Eratosthenes compared the Sun’s height at Syene and Alexandria. The difference in shadow angle gave him a fraction of a full circle. Using the estimated distance between the cities, he calculated Earth’s circumference. The exact length of the ancient stadion is uncertain. The method is striking because local observations yielded a planetary measurement.'],
    'image12.jpg','Geometrical diagram of Eratosthenes’s circumference method.'),
  add('serial-hipparchus',-130,['oko 130. p. n. e.','ok. 130 pr. n. št.','c. 130 BCE'],
    ['Hiparh prepoznaje precesiju ravnodnevnica.','Hiparh prepozna precesijo enakonočij.','Hipparchus recognizes precession of the equinoxes.'],
    ['Hiparh je uporedio nove položaje zvezda sa starijim merenjima. Uočio je spor pomak tačaka ravnodnevnice u odnosu na zvezde. Danas to nazivamo precesijom Zemljine ose. Pomak je veoma mali iz godine u godinu, ali postaje vidljiv kroz vekove. Otkriće je pokazalo snagu pažljivo čuvanih dugoročnih opažanja.',
     'Hiparh je primerjal nove lege zvezd s starejšimi meritvami. Opazil je počasno premikanje točk enakonočja glede na zvezde. Danes temu pravimo precesija Zemljine osi. Letni premik je majhen, skozi stoletja pa opazen. Odkritje kaže moč skrbno ohranjenih dolgoročnih opazovanj.',
     'Hipparchus compared fresh star positions with earlier measurements. He noticed a slow shift of the equinox points relative to the stars. Today we call this precession of Earth’s axis. The yearly change is tiny but becomes visible over centuries. The discovery showed the value of preserved long-term observations.'],
    'glossary/precession.svg','Diagram of axial precession.'),
  add('serial-khwarizmi',830,['oko 830.','ok. 830','c. 830 CE'],
    ['Al-Hvarizmi sastavlja astronomske tablice.','Al Hvarizmi sestavi astronomske tablice.','Al-Khwarizmi compiles astronomical tables.'],
    ['Al-Hvarizmi je u Bagdadu radio u okruženju u kome su prevođena i proučavana starija naučna dela. Sastavio je tablice za računanje položaja Sunca, Meseca i planeta. U njima su se ukrštale indijska, persijska i grčka tradicija. Njegov rad je kasnije preko prevoda uticao na evropske astronome. Tablice pokazuju da je srednjovekovna astronomija bila stvaralačka, a ne samo čuvanje antike.',
     'Al Hvarizmi je v Bagdadu deloval v okolju prevajanja in proučevanja starejših znanstvenih del. Sestavil je tablice za računanje leg Sonca, Lune in planetov. Povezal je indijsko, perzijsko in grško izročilo. Njegovo delo je prek prevodov vplivalo na evropske astronome. Tablice kažejo, da je bila srednjeveška astronomija ustvarjalna.',
     'Al-Khwarizmi worked in a Baghdad scholarly world that translated and studied older texts. He compiled tables for calculating positions of the Sun, Moon and planets. These drew on Indian, Persian and Greek traditions. Translations later carried his work to European astronomers. The tables show medieval astronomy was creative, not merely a storehouse for antiquity.'],
    'external/Muhammad_ibn_Musa_al-Khwarizmi.jpg','Modern statue representing al-Khwarizmi.',2),
  add('serial-battani',900,['oko 900.','ok. 900','c. 900 CE'],
    ['Al-Batani preciznije meri dužinu godine.','Al Batani natančneje izmeri dolžino leta.','Al-Battani refines the length of the year.'],
    ['Al-Batani je decenijama posmatrao Sunce, Mesec i planete. Iz merenja je dobio vrednost tropske godine blisku savremenoj. Ispravljao je ranije parametre Ptolomejevih proračuna. Pri računanju je sve više koristio trigonometrijske metode. Njegove tablice ostale su važna veza između antičke i kasnije astronomije.',
     'Al Batani je desetletja opazoval Sonce, Luno in planete. Iz meritev je dobil vrednost tropskega leta blizu današnji. Popravil je starejše parametre Ptolemajevih izračunov. Pri računanju je uporabljal več trigonometrije. Njegove tablice so ostale pomembna vez med antično in poznejšo astronomijo.',
     'Al-Battani observed the Sun, Moon and planets for decades. His measurements yielded a value for the tropical year close to the modern one. He revised parameters inherited from Ptolemy. His calculations made extensive use of trigonometry. His tables became an important link between ancient and later astronomy.'],
    'image1.png','Modern artistic image of al-Battani.',2),
  add('serial-ibn-haytham',1020,['oko 1020.','ok. 1020','c. 1020 CE'],
    ['Ibn al-Hajtam razvija eksperimentalnu optiku.','Ibn al Hajtam razvija eksperimentalno optiko.','Ibn al-Haytham develops experimental optics.'],
    ['Ibn al-Hajtam je proučavao kako se svetlost prostire i ulazi u oko. U svojim ogledima koristio je i tamnu komoru. Njegova Knjiga o optici povezala je geometriju sa opažanjem. Razumevanje svetlosti kasnije je bilo ključno za razvoj teleskopa. Naučni postupak ovde je važan koliko i pojedinačan rezultat.',
     'Ibn al Hajtam je proučeval širjenje svetlobe in njen vstop v oko. Pri poskusih je uporabljal tudi temno komoro. Knjiga o optiki je povezala geometrijo z opazovanjem. Razumevanje svetlobe je bilo pozneje ključno za teleskope. Znanstveni postopek je tu enako pomemben kot rezultat.',
     'Ibn al-Haytham studied how light travels and enters the eye. His experiments also used a dark chamber. His Book of Optics linked geometry with observation. Understanding light later became essential to telescope design. His method mattered as much as any single result.'],
    'image3.png','Camera obscura diagram associated with the history of optics.',2),
  add('serial-sacrobosco',1230,['oko 1230.','ok. 1230','c. 1230 CE'],
    ['Sakrobosko piše uticajan udžbenik o nebeskoj sferi.','Sacrobosco napiše vpliven učbenik o nebesni sferi.','Sacrobosco writes an influential astronomy textbook.'],
    ['Johanes de Sakrobosko napisao je kratko delo De sphaera mundi. Objasnio je osnovnu geometriju tada prihvaćenog geocentričnog neba. Knjiga se vekovima koristila u evropskim školama i univerzitetima. Njena široka upotreba pomogla je da astronomija postane deo formalnog obrazovanja. Ona istovremeno pokazuje koliko se jedan model može dugo zadržati u nastavi.',
     'Johannes de Sacrobosco je napisal kratko delo De sphaera mundi. Razložil je osnovno geometrijo tedaj sprejetega geocentričnega neba. Knjigo so stoletja uporabljali v evropskih šolah in na univerzah. Razširjenost je pomagala vključiti astronomijo v formalno izobraževanje. Hkrati kaže, kako dolgo lahko model ostane v pouku.',
     'Johannes de Sacrobosco wrote the short work De sphaera mundi. It explained the geometry of the accepted geocentric heavens. European schools and universities used it for centuries. Its reach made astronomy part of formal education. It also shows how long a model can remain in textbooks.'],
    'image9.png','Medieval illustration of Sacrobosco and a celestial sphere.',2),
  add('serial-tusi',1260,['oko 1260.','ok. 1260','c. 1260 CE'],
    ['Al-Tusi uvodi geometrijsku konstrukciju za kretanje planeta.','Al Tusi uvede geometrijsko konstrukcijo za gibanje planetov.','Al-Tusi introduces a new planetary geometry.'],
    ['Nasir al-Din al-Tusi kritikovao je delove Ptolomejevog modela planeta. Razvio je konstrukciju poznatu kao Tusijev par. Ona kombinuje dva kružna kretanja tako da nastaje pravolinijsko oscilovanje. Time je mogao da menja matematički model bez teleskopa. Njegov rad pokazuje kako teorijska kritika pokreće nova astronomska rešenja.',
     'Nasir al Din al Tusi je kritiziral dele Ptolemajevega modela planetov. Razvil je konstrukcijo, imenovano Tusijev par. Dve krožni gibanji se v njej združita v premočrtno nihanje. Tako je lahko spreminjal matematični model brez teleskopa. Njegovo delo kaže, kako teoretična kritika vodi do novih rešitev.',
     'Nasir al-Din al-Tusi criticized parts of Ptolemy’s planetary model. He developed the geometric construction called the Tusi couple. It combines two circular motions to produce a straight oscillation. This changed planetary mathematics without requiring a telescope. His work shows how theoretical criticism can generate new models.'],
    'image5.jpeg','Historical diagram of the Tusi couple.',2),
  add('serial-ulugh-observatory',1428,['1428.','1428','1428'],
    ['Ulug Beg gradi veliku opservatoriju u Samarkandu.','Ulugbeg zgradi veliki observatorij v Samarkandu.','Ulugh Beg builds a major observatory in Samarkand.'],
    ['Ulug Beg je u Samarkandu podigao opservatoriju sa velikim mernim instrumentom. Njena dimenzija omogućavala je precizno očitavanje položaja nebeskih tela. Tim astronoma radio je na proveri i obnovi starijih podataka. Njihov zvezdani katalog pojaviće se 1437. godine, što je već posebna stavka na liniji. Gradnja opservatorije pokazuje koliko su institucije važne za precizna merenja.',
     'Ulugbeg je v Samarkandu zgradil observatorij z velikim merilnim instrumentom. Velikost je omogočala natančno odčitavanje nebesnih leg. Skupina astronomov je preverjala in obnavljala starejše podatke. Zvezdni katalog je izšel leta 1437 in je na liniji že posebej prikazan. Gradnja kaže pomen ustanov za natančne meritve.',
     'Ulugh Beg built an observatory at Samarkand with a large measuring instrument. Its size allowed precise readings of celestial positions. His team checked and updated older observations. Their star catalogue appeared in 1437, already shown separately on this timeline. The observatory illustrates the importance of institutions for precision measurement.'],
    'image6.png','Ulugh Beg observatory in Samarkand.',2),
  add('serial-commentariolus',1514,['oko 1514.','ok. 1514','c. 1514'],
    ['Kopernikov Commentariolus kruži u rukopisu.','Kopernikov Commentariolus kroži v rokopisu.','Copernicus circulates the Commentariolus manuscript.'],
    ['Kopernik je u kratkom rukopisu izložio osnovne pretpostavke sistema sa Suncem blizu središta. Delo je kružilo među manjim brojem učenih ljudi. Nije još sadržalo potpunu matematičku razradu objavljenu 1543. godine. Predstavljalo je važan korak između privatne ideje i javne naučne rasprave. Datum nastanka je približan jer rukopis nije imao štampanu godinu izdanja.',
     'Kopernik je v kratkem rokopisu predstavil temelje sistema s Soncem blizu središča. Besedilo je krožilo med manjšim krogom učenjakov. Še ni vsebovalo celotne matematične razdelave iz leta 1543. Bilo je korak od zasebne zamisli do javne znanstvene razprave. Datum nastanka je približen, saj rokopis ni imel tiskane letnice.',
     'Copernicus set out the basic assumptions of a Sun-centered arrangement in a short manuscript. It circulated among a limited scholarly circle. It did not yet contain the full mathematics published in 1543. It was a step from private proposal to public scientific debate. Its date is approximate because the manuscript had no printed publication year.'],
    'image10.png','Modern illustration representing Copernicus.',2),
  add('serial-tycho-comet',1577,['1577.','1577','1577'],
    ['Tiho Brahe pokazuje da je kometa dalje od Meseca.','Tycho Brahe pokaže, da je komet dlje od Lune.','Tycho Brahe places a comet beyond the Moon.'],
    ['Tiho Brahe je proučavao sjajnu kometu iz 1577. godine. Poređenjem opažanja procenio je da je mnogo dalje od Meseca. Takav rezultat bio je težak za aristotelovsku sliku nepromenljivih nebeskih sfera. On je dodatno pokazao moć sistematskih preciznih merenja. Kometa nije bila samo atmosferska pojava, kako su mnogi ranije mislili.',
     'Tycho Brahe je proučeval svetli komet iz leta 1577. S primerjavo opazovanj je ocenil, da je dlje od Lune. To je bilo težko uskladiti z aristotelsko podobo nespremenljivih nebesnih sfer. Pokazal je tudi moč natančnih sistematičnih meritev. Komet ni bil zgolj pojav v ozračju, kot so nekateri menili.',
     'Tycho Brahe studied the bright comet of 1577. Comparing observations, he concluded it lay beyond the Moon. That challenged the Aristotelian picture of immutable celestial spheres. It also showed the power of systematic precision measurements. The comet was not merely an atmospheric phenomenon, as many had believed.'],
    'image14.png','Illustration of observation at Tycho Brahe’s Uraniborg.',2),
  add('serial-bruno',1600,['1600.','1600','1600'],
    ['Đordano Bruno umire posle inkvizicionog procesa.','Giordano Bruno umre po inkvizicijskem procesu.','Giordano Bruno is executed after an Inquisition trial.'],
    ['Đordano Bruno razmišljao je o beskrajnom svemiru sa mnoštvom svetova. Rimska inkvizicija pogubila ga je 1600. godine posle dugog procesa. Njegove kosmološke ideje bile su deo šireg skupa verskih i filozofskih stavova koji su ispitivani. Zato nije tačno svesti presudu samo na jednu astronomsku tvrdnju. Događaj pokazuje napetost između slobodnog mišljenja i tadašnjih institucija.',
     'Giordano Bruno je razmišljal o neskončnem vesolju z mnogimi svetovi. Rimska inkvizicija ga je leta 1600 po dolgem procesu usmrtila. Kozmološke ideje so bile del širšega sklopa verskih in filozofskih stališč. Sodbe zato ni pravilno pripisati le eni astronomski trditvi. Dogodek kaže napetost med svobodnim mišljenjem in tedanjimi ustanovami.',
     'Giordano Bruno argued for an infinite universe containing many worlds. The Roman Inquisition executed him in 1600 after a long trial. His cosmological views formed part of a wider set of religious and philosophical positions under scrutiny. The judgment cannot accurately be reduced to a single astronomical claim. The episode shows tensions between intellectual freedom and institutions of the time.'],
    'image12.png','Giordano Bruno monument in Rome.',2),
  add('serial-jupiter-moons',1610.1,['1610.','1610','1610'],
    ['Galileo otkriva četiri velika Jupiterova meseca.','Galileo odkrije štiri velike Jupitrove lune.','Galileo discovers Jupiter’s four large moons.'],
    ['Galileo je u januaru 1610. pratio male svetle tačke uz Jupiter. Njihov promenljiv raspored pokazao je da kruže oko planete. Danas su poznate kao Io, Evropa, Ganimed i Kalisto. Otkriće je oslabilo tvrdnju da se baš sve u kosmosu okreće oko Zemlje. Samo po sebi ipak nije bilo potpun dokaz heliocentričnog sistema.',
     'Galileo je januarja 1610 spremljal majhne svetle pike ob Jupitru. Spreminjanje njihovih leg je pokazalo, da krožijo okoli planeta. Danes jih poznamo kot Io, Evropo, Ganimed in Kalisto. Odkritje je oslabilo trditev, da se prav vse vrti okoli Zemlje. Samo po sebi pa ni dokončno dokazalo heliocentričnega sistema.',
     'In January 1610 Galileo tracked small bright points near Jupiter. Their changing positions showed that they orbited the planet. Today we call them Io, Europa, Ganymede and Callisto. The discovery weakened the claim that everything circles Earth. By itself it was not a complete proof of heliocentrism.'],
    'image17.png','Galileo’s surviving telescopes in Florence.',2),
  add('serial-kepler-third',1619,['1619.','1619','1619'],
    ['Kepler objavljuje treći zakon kretanja planeta.','Kepler objavi tretji zakon gibanja planetov.','Kepler publishes his third law of planetary motion.'],
    ['Kepler je otkrio vezu između vremena obilaska planete i veličine njene orbite. Kvadrat perioda srazmeran je kubu velike poluose orbite. To znači da udaljenije planete u proseku obilaze Sunce mnogo sporije. Njegova prva dva zakona iz 1609. već su prikazana na liniji. Treći zakon dao je dodatni matematički obrazac koji će Njutn kasnije objasniti gravitacijom.',
     'Kepler je odkril zvezo med obhodnim časom planeta in velikostjo njegove tirnice. Kvadrat periode je sorazmeren s kubom velike polosi tirnice. Oddaljenejši planeti zato obkrožijo Sonce počasneje. Prva dva zakona iz leta 1609 sta na liniji že prikazana. Tretji je dodal vzorec, ki ga je Newton pozneje pojasnil s težnostjo.',
     'Kepler found a relation between a planet’s orbital period and orbit size. The square of the period is proportional to the cube of the orbit’s semimajor axis. More distant planets therefore take much longer to circle the Sun. His first two laws of 1609 are already represented on the timeline. The third supplied a pattern Newton would later explain through gravity.'],
    'image15.png','Modern illustration representing Kepler.',2),
  add('serial-boscovich',1758,['1758.','1758','1758'],
    ['Bošković objavljuje Teoriju prirodne filozofije.','Bošković objavi Teorijo naravne filozofije.','Bošković publishes his Theory of Natural Philosophy.'],
    ['Ruđer Bošković je 1758. objavio teoriju u kojoj materiju opisuje kroz tačke i sile. Njegov rad prvenstveno pripada istoriji fizike, ali je nastao u širokom programu prirodne filozofije i astronomije. Bošković je proučavao i nebeske pojave, merenja i instrumente. Ova stavka prikazuje regionalni doprinos razvoju matematičkog razumevanja prirode. Njegovu teoriju ne treba izjednačavati sa današnjom atomskom fizikom.',
     'Ruđer Bošković je leta 1758 objavil teorijo, ki snov opisuje s točkami in silami. Delo sodi predvsem v zgodovino fizike, nastalo pa je v širšem programu naravne filozofije in astronomije. Bošković je proučeval tudi nebesne pojave, meritve in instrumente. Dogodek kaže regionalni prispevek k matematičnemu razumevanju narave. Teorije ne gre enačiti z današnjo atomsko fiziko.',
     'Ruđer Bošković published a theory of matter as points and forces in 1758. It chiefly belongs to physics history, but arose within a wider program of natural philosophy and astronomy. Bošković also studied celestial phenomena, measurement and instruments. This entry marks a regional contribution to mathematical accounts of nature. His theory should not be equated with modern atomic physics.'],
    'image18.png','Modern artistic image of Ruđer Bošković.',2),
  add('serial-orfelin',1783,['1783.','1783','1783'],
    ['Orfelin objavljuje Vječni kalendar.','Orfelin objavi Večni koledar.','Orfelin publishes the Eternal Calendar.'],
    ['Zaharije Orfelin objavio je Vječni kalendar u Beču. Knjiga nije bila samo spisak datuma, već i popularno objašnjenje prirode i neba. Čitaocima je predstavljala astronomiju i Kopernikov sistem na pristupačnom jeziku. U istoriji srpske naučne pismenosti ima posebno mesto. Pokazuje kako se naučno znanje širi izvan uskog kruga stručnjaka.',
     'Zaharija Orfelin je na Dunaju objavil Večni koledar. Knjiga ni bila le seznam datumov, temveč tudi poljudna razlaga narave in neba. Bralcem je približala astronomijo in Kopernikov sistem. V zgodovini srbske znanstvene pismenosti ima posebno mesto. Kaže, kako znanje doseže ljudi zunaj ozkega kroga strokovnjakov.',
     'Zaharije Orfelin published the Eternal Calendar in Vienna. It was more than a list of dates: it explained nature and the sky for general readers. It presented astronomy and the Copernican system in accessible language. It holds a special place in the history of Serbian science education. It shows how knowledge can travel beyond specialists.'],
    'image19.png','Portrait of Zaharije Orfelin.',2),
  add('serial-stojkovic',1801,['1801–1803.','1801–1803','1801–1803'],
    ['Stojković objavljuje trotomnu Fiziku na srpskom.','Stojković objavi tridelno Fiziko v srbščini.','Stojković publishes a three-volume Physics in Serbian.'],
    ['Atanasije Stojković objavio je između 1801. i 1803. trotomno delo Fizika. Knjiga je prirodne nauke objašnjavala čitaocima na razumljivom jeziku. Obuhvatala je i tadašnje znanje o Zemlji i nebu. Njen značaj nije u novom astronomskom otkriću, već u prenosu znanja. To je deo istorije obrazovanja bez kog otkrića teško postaju opštepoznata.',
     'Atanasije Stojković je med letoma 1801 in 1803 objavil tridelno Fiziko. Naravoslovje je razlagala bralcem v razumljivem jeziku. Obravnavala je tudi tedanje znanje o Zemlji in nebu. Pomen knjige ni novo astronomsko odkritje, temveč širjenje znanja. To je del zgodovine izobraževanja, brez katerega odkritja težko postanejo splošno znana.',
     'Between 1801 and 1803 Atanasije Stojković published a three-volume Physics. It explained natural science in language intended for a broad readership. It also covered contemporary ideas about Earth and the sky. Its importance lies in communicating knowledge, not in a new astronomical discovery. Such education helps discoveries become widely understood.'],
    'image20.png','Modern artistic representation of Atanasije Stojković.',2)
];
