astronomyAdditions.push(
  add('serial-egypt-calendar',-3000,['treći milenijum p. n. e.','3. tisočletje pr. n. št.','third millennium BCE'],
    ['Egipćani razvijaju kalendar od 365 dana.','Egipčani razvijejo koledar s 365 dnevi.','Egyptians develop a 365-day calendar.'],
    ['Egipatski građanski kalendar imao je dvanaest meseci po trideset dana i još pet dodatnih dana. To je ukupno 365 dana. Posmatranja zvezde Sirijus i sezonskih promena bila su važna za vezu neba i kalendara. Pošto kalendar nije dodavao prestupni dan, postepeno se pomerao u odnosu na godišnja doba. Tačan trenutak njegovog uvođenja nije pouzdano poznat.',
     'Egiptovski civilni koledar je imel dvanajst mesecev po trideset dni in še pet dodatnih dni. Skupaj je obsegal 365 dni. Opazovanja zvezde Sirij in letnih časov so povezovala nebo s koledarjem. Ker ni dodajal prestopnega dne, se je počasi premikal glede na letne čase. Natančen čas njegove uvedbe ni zanesljivo znan.',
     'The Egyptian civil calendar had twelve thirty-day months plus five extra days. That made 365 days. Observations of Sirius and seasonal change helped connect the sky to the calendar. Without a leap day it slowly drifted relative to the seasons. The exact date of its introduction is uncertain.'],
    'image7.jpg','Ancient Egyptian merket used to establish direction.'),
  add('serial-alfonsine',1270,['oko 1270.','ok. 1270','c. 1270'],
    ['Nastaju Alfonsinske tablice za položaje planeta.','Nastanejo Alfonsinske tablice za lege planetov.','The Alfonsine Tables compile planetary positions.'],
    ['U Kastilji je pod pokroviteljstvom Alfonsa X nastao skup astronomskih tablica. Jevrejski, hrišćanski i muslimanski učenjaci radili su u povezanoj tradiciji prevoda i proračuna. Tablice su pomagale da se izračunaju položaji planeta za različite datume. Na Zapadu su ostale uticajne nekoliko vekova. Rad je nastajao tokom 1260-ih i 1270-ih, pa jedna tačna godina nije opravdana.',
     'V Kastilji so pod pokroviteljstvom Alfonza X nastale astronomske tablice. Judovski, krščanski in muslimanski učenjaki so sodelovali v izročilu prevodov in računanja. Tablice so pomagale izračunati lege planetov za različne datume. Na Zahodu so ostale vplivne več stoletij. Nastajale so v 1260-ih in 1270-ih, zato ena natančna letnica ni upravičena.',
     'Astronomical tables were compiled in Castile under Alfonso X. Jewish, Christian and Muslim scholars worked within a connected tradition of translation and calculation. The tables helped compute planetary positions for given dates. They remained influential in Europe for centuries. Compilation extended through the 1260s and 1270s, so one exact year would be misleading.'],
    'external/alfonsine-table.jpg','Page of a later manuscript of the Alfonsine Tables.',2),
  add('serial-uraniborg',1576,['1576.','1576','1576'],
    ['Tiho Brahe osniva opservatoriju Uraniborg.','Tycho Brahe ustanovi observatorij Uraniborg.','Tycho Brahe establishes Uraniborg.'],
    ['Danski kralj je Tihu Braheu omogućio izgradnju opservatorije na ostrvu Hven. Uraniborg je objedinjavala merenja, instrumente i rad saradnika. Kasnije je nastala i Stjerneborg, delom podzemna opservatorija za stabilnije instrumente. Prikupljeni podaci bili su mnogo precizniji od većine ranijih opažanja bez teleskopa. Kepler ih je kasnije iskoristio u radu na zakonima planetarnih putanja.',
     'Danski kralj je Tycho Braheju omogočil gradnjo observatorija na otoku Hven. Uraniborg je združeval meritve, instrumente in delo sodelavcev. Pozneje je nastal še deloma podzemni Stjerneborg za stabilnejše instrumente. Zbrani podatki so bili izredno natančni za dobo brez teleskopa. Kepler jih je pozneje uporabil pri zakonih planetnih tirnic.',
     'The Danish king supported Tycho Brahe’s observatory on the island of Hven. Uraniborg combined instruments, measurements and a team of collaborators. A partly underground observatory, Stjerneborg, followed for greater stability. The observations were exceptionally precise for the pre-telescope era. Kepler later used them to derive his planetary laws.'],
    'image14.png','Illustration of the Uraniborg observatory at work.',2),
  add('serial-galileo-telescope',1609.1,['1609.','1609','1609'],
    ['Galileo usmerava teleskop ka nebu.','Galileo usmeri teleskop proti nebu.','Galileo turns a telescope toward the sky.'],
    ['Galileo nije izmislio teleskop, ali je brzo poboljšao njegovu optiku. Godine 1609. počeo je sistematski da ga koristi za posmatranje neba. Video je detalje koji golim okom nisu bili dostupni. Njegova opažanja Meseca i Jupitera objavljena su 1610. godine. Instrument je otvorio novu epohu posmatračke astronomije.',
     'Galileo ni izumil teleskopa, vendar je hitro izboljšal njegovo optiko. Leta 1609 ga je začel sistematično uporabljati za opazovanje neba. Videl je podrobnosti, ki s prostim očesom niso bile dostopne. Opažanja Lune in Jupitra je objavil leta 1610. Instrument je odprl novo dobo opazovalne astronomije.',
     'Galileo did not invent the telescope, but he rapidly improved its optics. In 1609 he began using it systematically on the sky. It revealed details invisible to the naked eye. He published observations of the Moon and Jupiter in 1610. The instrument opened a new era of observational astronomy.'],
    'image17.png','Galileo’s surviving telescopes and lenses.',2),
  add('serial-rudolphine',1627,['1627.','1627','1627'],
    ['Kepler objavljuje Rudolfinske tablice.','Kepler objavi Rudolfinske tablice.','Kepler publishes the Rudolphine Tables.'],
    ['Rudolfinske tablice spojile su Tihova precizna opažanja i Keplerov model eliptičnih orbita. Omogućavale su bolje proračune položaja planeta. Nisu bile samo teorijski rad, već praktičan alat za buduća posmatranja. Na osnovu takvih predviđanja planirano je posmatranje Merkurovog prelaska preko Sunčevog diska. Tablice su pokazale da novi model neba može dati proverljive rezultate.',
     'Rudolfinske tablice so združile Tychova natančna opazovanja in Keplerjev model eliptičnih tirnic. Omogočale so boljše izračune leg planetov. Bile so praktično orodje za nova opazovanja, ne le teorija. Na podlagi takih napovedi so načrtovali opazovanje prehoda Merkurja čez Sonce. Tablice so pokazale preverljivo moč novega modela neba.',
     'The Rudolphine Tables combined Tycho’s precise observations with Kepler’s elliptical-orbit model. They enabled improved calculations of planetary positions. They were a practical observing tool as well as a theoretical achievement. Predictions based on them helped plan a Mercury transit observation. The tables showed that a new model of the heavens could yield testable results.'],
    'image15.png','Modern illustration representing Johannes Kepler.',2),
  add('serial-mercury-transit',1631,['1631.','1631','1631'],
    ['Gasendi prvi posmatra predviđeni tranzit Merkura.','Gassendi prvi opazuje napovedani prehod Merkurja.','Gassendi observes the predicted transit of Mercury.'],
    ['Pjer Gasendi je u Parizu posmatrao Merkur kao sićušnu tamnu tačku ispred Sunca. Prelazak je ranije predvideo Kepler koristeći svoje astronomske proračune. Gasendi je sliku Sunca projektovao teleskopom radi bezbednog posmatranja. Bio je to prvi zabeleženi tranzit planete posmatran teleskopom. Savremena prateća slika prikazuje isti tip pojave, ali nije snimak iz 1631. godine.',
     'Pierre Gassendi je v Parizu opazoval Merkur kot drobno temno piko pred Soncem. Prehod je prej napovedal Kepler z astronomskimi izračuni. Gassendi je za varno opazovanje teleskopsko sliko projiciral. To je bil prvi zapisani teleskopsko opazovani prehod planeta. Spremljevalna sodobna slika prikazuje isti pojav, ne posnetka iz leta 1631.',
     'In Paris, Pierre Gassendi saw Mercury as a tiny dark point against the Sun. Kepler had predicted the transit using his astronomical calculations. Gassendi projected the Sun’s telescopic image for safe observation. It became the first recorded planetary transit observed with a telescope. The accompanying modern image shows the same kind of event, not the 1631 observation.'],
    'external/mercury-transit.jpg','Modern NASA image of Mercury crossing the Sun.',2),
  add('serial-galileo-trial',1633,['1633.','1633','1633'],
    ['Galileo je osuđen posle rasprave o dva sistema sveta.','Galileo je obsojen po razpravi o dveh sistemih sveta.','Galileo is tried over his Dialogue on two world systems.'],
    ['Galilejev Dijalog o dva glavna sistema sveta objavljen je 1632. godine. Sledeće godine Rimska inkvizicija sudila mu je zbog zagovaranja heliocentrizma. Morao je da se odrekne svojih stavova i ostatak života proveo je u kućnom pritvoru. Istorija procesa uključuje i tadašnje verske, političke i lične odnose. Posmatrački dokazi nastavili su da menjaju astronomiju uprkos presudi.',
     'Galilejev Dialog o dveh glavnih svetovnih sistemih je izšel leta 1632. Naslednje leto mu je rimska inkvizicija sodila zaradi zagovarjanja heliocentrizma. Svoje trditve je moral preklicati in preostanek življenja preživel v hišnem priporu. Proces je vključeval tudi verske, politične in osebne odnose tistega časa. Opazovalni dokazi so astronomijo spreminjali kljub sodbi.',
     'Galileo published his Dialogue Concerning the Two Chief World Systems in 1632. The Roman Inquisition tried him the following year over his support for heliocentrism. He was forced to recant and spent the rest of his life under house arrest. The case also involved the religious, political and personal relations of the time. Observational evidence continued to reshape astronomy despite the verdict.'],
    'image16.png','Modern artistic representation of Galileo Galilei.',2)
);
for(const [key,file,source,credit,license] of [
  ['serial-alfonsine','alfonsine-table.jpg','https://commons.wikimedia.org/wiki/File:Alfonsine_Table_in_Bnf_7432.jpg','Conrad Heingartner / Bibliothèque nationale de France','Public domain'],
  ['serial-mercury-transit','mercury-transit.jpg','https://commons.wikimedia.org/wiki/File:Transit_of_Mercury_on_May_9,_2016.jpg','NASA Solar Dynamics Observatory','Public domain']
])Object.assign(astronomyAdditions.find(e=>e.key===key).media,{file:'serial-astronomy/external/'+file,source,credit,license});

astronomyAdditions.push(
  add('serial-pythagoreans',-500.2,['oko 500. p. n. e.','ok. 500 pr. n. št.','c. 500 BCE'],
    ['Pitagorejci povezuju oblik Zemlje i geometriju.','Pitagorejci povezujejo obliko Zemlje in geometrijo.','Pythagoreans link Earth’s shape with geometry.'],
    ['Pitagorejska škola posebno je isticala matematički red prirode. U antičkim prikazima njeni mislioci povezivani su i sa idejom sferne Zemlje. Nije moguće pouzdano pripisati tu ideju lično Pitagori niti ga proglasiti prvim čovekom koji ju je izneo. Kasniji astronomi navodili su opažanja, poput oblika Zemljine senke tokom pomračenja Meseca. Ovaj korak pokazuje prelaz od filozofske zamisli ka proverljivim argumentima.',
     'Pitagorejska šola je poudarjala matematični red narave. Antična pričevanja njene mislece povezujejo tudi z zamislijo kroglaste Zemlje. Zamisli ne moremo zanesljivo pripisati Pitagori osebno ali ga razglasiti za prvega. Poznejši astronomi so dodali opažanja, na primer obliko Zemljine sence ob Luninem mrku. To kaže prehod od filozofske domneve k preverljivim razlogom.',
     'The Pythagorean school emphasized mathematical order in nature. Ancient accounts also associate its thinkers with the idea of a spherical Earth. We cannot securely credit that idea to Pythagoras personally or call him its first proponent. Later astronomers added observations such as Earth’s curved shadow in lunar eclipses. This marks a shift from philosophical suggestion toward testable arguments.'],
    'image9.png','Modern artistic representation of Pythagoras.'),
  add('serial-saros',-500.1,['oko 500. p. n. e.','ok. 500 pr. n. št.','c. 500 BCE'],
    ['Vavilonski zapisi otkrivaju pravilnost pomračenja.','Babilonski zapisi razkrijejo vzorec mrkov.','Babylonian records reveal an eclipse cycle.'],
    ['Duga posmatranja pokazala su da se slične okolnosti pomračenja vraćaju posle 223 sinodička meseca. Danas taj period nazivamo Saros i traje oko osamnaest godina i jedanaest dana. Zbog dodatnih osam sati sledeće pomračenje ne mora biti vidljivo sa istog mesta na Zemlji. Pravilnost je omogućavala procenu vremena budućih pomračenja, ali ne potpuno precizno predviđanje svakog lokalnog prizora. Tačan datum prvog prepoznavanja ciklusa nije poznat.',
     'Dolga opazovanja so pokazala, da se podobne okoliščine mrkov ponovijo po 223 sinodskih mesecih. Obdobje imenujemo saros in traja približno osemnajst let ter enajst dni. Zaradi dodatnih osmih ur naslednji mrk ni nujno viden z istega kraja. Vzorec je pomagal ocenjevati prihodnje mrke, ne pa povsem natančno napovedati vsakega lokalnega pojava. Točna letnica odkritja ni znana.',
     'Long records showed that similar eclipse conditions return after 223 synodic months. We now call this period a saros, about eighteen years and eleven days. Because of an additional eight hours, the next eclipse need not be visible from the same place. The pattern helped estimate future eclipses without predicting every local view precisely. The exact date when it was first recognized is unknown.'],
    'external/saros145.gif','NASA animation showing successive eclipses in one saros series.'),
  add('serial-aristotle',-350,['oko 350. p. n. e.','ok. 350 pr. n. št.','c. 350 BCE'],
    ['Aristotel obrazlaže sfernu Zemlju u geocentričnom kosmosu.','Aristotel utemelji kroglasto Zemljo v geocentričnem vesolju.','Aristotle argues for a spherical Earth in a geocentric cosmos.'],
    ['Aristotel je navodio Zemljinu zakrivljenu senku na Mesecu tokom pomračenja. Primećivao je i promenu vidljivih zvezda pri putovanju na sever ili jug. To su bili razumni argumenti da je Zemlja približno sferna. Istovremeno je smatrao da Zemlja miruje u središtu kosmosa. Njegova uticajna sinteza spojila je tačan zaključak o obliku sa pogrešnim modelom kretanja planeta.',
     'Aristotel je opozarjal na ukrivljeno Zemljino senco na Luni med mrkom. Opazil je tudi menjavo vidnih zvezd pri potovanju proti severu ali jugu. To so bili razumni razlogi za približno kroglasto Zemljo. Hkrati je menil, da Zemlja miruje v središču vesolja. Njegova vplivna sinteza je združila pravilen sklep o obliki z napačnim modelom gibanja planetov.',
     'Aristotle pointed to Earth’s curved shadow on the Moon during eclipses. He also noted how visible stars change as travelers move north or south. These were good arguments that Earth is approximately spherical. He nevertheless placed a stationary Earth at the center of the cosmos. His influential synthesis joined a correct conclusion about shape to an incorrect model of planetary motion.'],
    'external/aristotle-bust.jpg','Ancient bust traditionally identified as Aristotle.')
);
Object.assign(astronomyAdditions.find(e=>e.key==='serial-saros').media,{file:'serial-astronomy/external/saros145.gif',source:'https://commons.wikimedia.org/wiki/File:Saros145.gif',credit:'Fred Espenak / NASA',license:'Public domain'});
Object.assign(astronomyAdditions.find(e=>e.key==='serial-aristotle').media,{file:'serial-astronomy/external/aristotle-bust.jpg',source:'https://commons.wikimedia.org/wiki/File:Aristotle_Altemps_Detail.jpg',credit:'Jastrow',license:'Public domain'});
astronomyAdditions.push(add('serial-zodiac',-500,['oko 500. p. n. e.','ok. 500 pr. n. št.','c. 500 BCE'],
  ['U Vavilonu se oblikuje zodijački pojas sa dvanaest delova.','V Babilonu se oblikuje zodiakalni pas z dvanajstimi deli.','Babylonians develop a twelve-part zodiac.'],
  ['Vavilonski astronomi povezivali su nebeski pojas kojim se prividno kreću Sunce, Mesec i planete sa grupama zvezda. Tokom prvog milenijuma pre nove ere razvijao se sistem dvanaest zodijačkih znakova. Kasnije je svaki znak postao matematički odsek od trideset stepeni. Ova podela pomagala je beleženju i računanju nebeskih položaja. Današnja sazvežđa imaju drugačije, nejednake zvanične granice, pa znak i sazvežđe nisu isto.',
   'Babilonski astronomi so povezali pas neba, po katerem se navidezno gibljejo Sonce, Luna in planeti, z zvezdnimi skupinami. V prvem tisočletju pred našim štetjem se je razvijal sistem dvanajstih zodiakalnih znamenj. Pozneje je vsako pomenilo matematični odsek tridesetih stopinj. Delitev je olajšala zapisovanje in računanje nebesnih leg. Današnja ozvezdja imajo drugačne, neenake uradne meje, zato znamenje ni isto kot ozvezdje.',
   'Babylonian astronomers associated the sky band traversed by the Sun, Moon and planets with groups of stars. During the first millennium BCE a twelve-sign zodiac developed. Each sign later became a mathematical thirty-degree segment. This division aided the recording and calculation of celestial positions. Modern constellations have different, unequal official boundaries, so a sign is not the same as a constellation.'],
  'external/zodiac-circle.svg','Diagram of the twelve zodiac signs.'));
Object.assign(astronomyAdditions.find(e=>e.key==='serial-zodiac').media,{file:'serial-astronomy/external/zodiac-circle.svg',source:'https://commons.wikimedia.org/wiki/File:Zodiac_circle.svg',credit:'Kwamikagami',license:'https://creativecommons.org/licenses/by-sa/4.0/'});
astronomyAdditions.push(...astronomyPart3Additions);
